Contract ManageItemCRUDService::createItem(barcode:Integer,name:String,price:Real,stocknumber:Integer,orderprice:Real): Boolean {
          definition:
          foundItem:Item = Item.allInstance()->any(i | i.Barcode = barcode)


            postcondition:
          if foundItem.oclIsUndefined() then let newItem:Item in newItem.oclIsNew() and Item.allInstance()->includes(newItem) and newItem.Barcode=barcode and newItem.Name=name and newItem.Price=price and newItem.StockNumber=stocknumber and newItem.OrderPrice=orderprice and result=true else result=false endif

        }
